-- Ensure status history is generated by the database and cannot be forged
-- by direct client calls. Fixed search_path prevents object-shadowing attacks.

begin;

create or replace function public.touch_church_member_record()
returns trigger
language plpgsql
set search_path = pg_catalog, public
as $function$
begin
  new.updated_at = now();
  return new;
end;
$function$;

create or replace function public.record_church_member_status_change()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public
as $function$
begin
  if tg_op = 'INSERT' then
    insert into public.church_member_status_history
      (organization_id, member_record_id, previous_status, new_status, note, changed_by)
    values
      (new.organization_id, new.id, null, new.membership_status, 'Registo inicial', auth.uid());
  elsif new.membership_status is distinct from old.membership_status then
    insert into public.church_member_status_history
      (organization_id, member_record_id, previous_status, new_status, note, changed_by)
    values
      (new.organization_id, new.id, old.membership_status, new.membership_status,
       'Alteração de estado da membresia', auth.uid());
  end if;
  return new;
end;
$function$;

drop trigger if exists church_member_records_touch on public.church_member_records;
create trigger church_member_records_touch
before update on public.church_member_records
for each row execute function public.touch_church_member_record();

drop trigger if exists church_member_status_change on public.church_member_records;
create trigger church_member_status_change
after insert or update of membership_status on public.church_member_records
for each row execute function public.record_church_member_status_change();

revoke all on function public.record_church_member_status_change() from public, anon, authenticated;
revoke all on function public.touch_church_member_record() from public, anon, authenticated;

commit;
